#include "ImmediateOptionsCommit.hpp"
#include "OptionsModel.hpp"
#include "FileInfoDecision.hpp"
#include <iostream>
namespace udm {struct CatalogCheckpointTestAccess {static void observe(Manager& m,std::function<void(const char*)> action){Lock lock(m.mutex);m.catalogCheckpoint=std::move(action);}};}
using namespace udm;
template<class F>static bool until(F f){const auto end=GetTickCount64()+6000;while(!f()&&GetTickCount64()<end)Sleep(1);return f();}
int wmain(int argc,wchar_t** argv){
 if(argc!=2)return 2;const auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;
 const auto check=[&](bool ok,const char* name){checks.push_back({{"name",name},{"passed",ok}});if(!ok)throw std::runtime_error(name);};
 try{
  Manager manager(root/L"catalog");auto settings=manager.state["Settings"];settings["DownloadFolder"]=utf8((root/L"files").wstring());settings["CategoryPaths"]=legacyDictionary(Json{{"Archives",utf8((root/L"archives").wstring())}});settings["CategoryRememberLast"]={{"Archives",true},{"Video",false}};settings["UseServerDate"]=false;manager.setSettings(settings);
  auto folder=applyImmediateOptions(manager,{ImmediateOptionsKind::CategoryFolder,"Video",utf8((root/L"video").wstring())});check(str(dictionary(folder.settings["CategoryPaths"]),"Video")==utf8((root/L"video").wstring()),"Category Browse returns its actual accepted path");check(str(dictionary(manager.state["Settings"]["CategoryPaths"]),"Archives")==utf8((root/L"archives").wstring())&&yes(manager.state["Settings"]["CategoryRememberLast"],"Archives"),"Category Browse preserves the other categories and remember choices");check(folder.fields==std::vector<std::string>{"CategoryPaths","CategoryRememberLast"}&&folder.settings.size()==2&&!folder.settings.contains("UserAgent"),"Only the affected category preferences enter the owned acknowledgement");
  auto remember=applyImmediateOptions(manager,{ImmediateOptionsKind::CategoryRemember,"Video",{},true});check(yes(remember.settings["CategoryRememberLast"],"Video")&&yes(remember.settings["CategoryRememberLast"],"Archives"),"Remember-path changes only the accepted category");
  auto date=applyImmediateOptions(manager,{ImmediateOptionsKind::ServerDate,{},{},true});check(date.fields==std::vector<std::string>{"UseServerDate"}&&yes(date.settings,"UseServerDate")&&date.settings.size()==1,"Server-date saves only its owned boolean setting");
  auto temporary=applyImmediateOptions(manager,{ImmediateOptionsKind::TemporaryFolder,{},utf8((root/L"temporary").wstring())});check(str(temporary.settings,"TemporaryFolder")==utf8((root/L"temporary").wstring())&&temporary.fields==std::vector<std::string>{"TemporaryFolder"},"Temporary Browse returns its accepted absolute folder");
  auto reset=applyImmediateOptions(manager,{ImmediateOptionsKind::TemporaryFolder,{},{}});check(str(reset.settings,"TemporaryFolder").empty()&&manager.state["Settings"]["TemporaryFolder"]=="","Use default clears the override without inventing a destination");
  Json baseline=settings,draft=baseline;draft["UserAgent"]="Unfinished agent";acknowledgeImmediateOptions(draft,baseline,remember);check(str(draft,"UserAgent")=="Unfinished agent"&&str(baseline,"UserAgent")==str(settings,"UserAgent"),"Immediate acknowledgement preserves unrelated draft choices and their original baseline");check(draft["CategoryPaths"]==baseline["CategoryPaths"]&&draft["CategoryRememberLast"]==baseline["CategoryRememberLast"],"Acknowledged category fields become the new partial baseline");
  auto current=manager.state["Settings"];current["CategoryRememberLast"]["Video"]=false;auto merged=mergeOptionsDraft(baseline,draft,current);check(!yes(merged["CategoryRememberLast"],"Video")&&str(merged,"UserAgent")=="Unfinished agent","A later full Options save preserves newer category changes while applying its unrelated unfinished draft");
  const auto reject=[&](ImmediateOptionsDraft bad,const char* name){auto before=manager.snapshot();const auto disk=readText(manager.root/L"state.json");bool failed=false;try{applyImmediateOptions(manager,bad);}catch(...){failed=true;}check(failed&&manager.snapshot()==before&&readText(manager.root/L"state.json")==disk,name);};
  reject({ImmediateOptionsKind::CategoryFolder,"Video","relative"},"A relative category folder cannot mutate memory or the saved catalog");reject({ImmediateOptionsKind::CategoryFolder,"Video",{}},"A missing category destination cannot be accepted");reject({ImmediateOptionsKind::TemporaryFolder,{},"relative"},"A relative temporary folder cannot mutate memory or disk");reject({ImmediateOptionsKind::CategoryRemember,"removed-category",{},true},"A removed category cannot be silently recreated by a stale remember checkbox");reject({static_cast<ImmediateOptionsKind>(99),{},{},false},"An unknown immediate command cannot mutate settings");
  FileInfoDecisionTask task;auto accepted=std::make_shared<ImmediateOptionsResult>();
  {
   std::promise<void> release;auto gate=release.get_future().share();std::atomic_bool held=false;std::thread writer([&]{Lock lock(manager.mutex);manager.state["Settings"]["UserAgent"]="Concurrent accepted agent";held=true;gate.wait();});struct Join{std::promise<void>& release;std::thread& writer;~Join(){try{release.set_value();}catch(...){}if(writer.joinable())writer.join();}} cleanup{release,writer};check(until([&]{return held.load();}),"A real catalog writer precedes accepted immediate work");
   task.startAction(manager,[&]{*accepted=applyImmediateOptions(manager,{ImmediateOptionsKind::CategoryRemember,"Video",{},false});return FileInfoDecisionResult{};});check(task.valid()&&manager.fileInfoDecisionPending&&held&&!task.ready(),"The initiating thread returns while its owned save waits on the actual Manager mutex");bool duplicate=false;try{task.startAction(manager,[]{return FileInfoDecisionResult{};});}catch(...){duplicate=true;}check(duplicate&&manager.fileInfoDecisionPending,"A duplicate write cannot replace the accepted command or release its global owner");release.set_value();writer.join();check(until([&]{return task.ready();}),"The immediate worker completes after the existing writer releases the model");task.get();check(manager.fileInfoDecisionPending&&str(manager.state["Settings"],"UserAgent")=="Concurrent accepted agent","The worker preserves the latest unrelated settings and keeps its guard through UI acknowledgement");task.release();check(!manager.fileInfoDecisionPending&&!yes(accepted->settings["CategoryRememberLast"],"Video"),"Acknowledging the accepted result releases ownership without another model read");
  }
  auto before=manager.snapshot();const auto disk=readText(manager.root/L"state.json");CatalogCheckpointTestAccess::observe(manager,[](const char* stage){if(std::string(stage)=="temporary-flushed")throw std::runtime_error("Owned immediate checkpoint failure");});bool failed=false;task.startAction(manager,[&]{applyImmediateOptions(manager,{ImmediateOptionsKind::ServerDate,{},{},false});return FileInfoDecisionResult{};});check(until([&]{return task.ready();}),"A failed durable immediate save settles on its worker");try{task.get();}catch(...){failed=true;}check(failed&&manager.fileInfoDecisionPending&&manager.snapshot()==before&&readText(manager.root/L"state.json")==disk,"A checkpoint failure restores all settings and saved bytes while the error retains its owner");task.release();CatalogCheckpointTestAccess::observe(manager,{});
  auto retry=applyImmediateOptions(manager,{ImmediateOptionsKind::ServerDate,{},{},false});check(!yes(retry.settings,"UseServerDate")&&!manager.fileInfoDecisionPending,"Explicit retry succeeds after a failed write without a leaked decision guard");manager.stop();
 }catch(const std::exception& failure){error=failure.what();}
 atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;
}
